A.DefaultEntries[#A.DefaultEntries+1]={id=[==[bufffood:de:regular:say:universal:native-0100-06]==],category="bufffood",language="de",stock=false,channel="say",source="universal",migrationMatch=false,text=[==[Wir haben die Riemen geprüft. Jetzt sind die Vorräte dran.]==]}
A.DefaultEntries[#A.DefaultEntries+1]={id=[==[bufffood:de:regular:say:universal:native-0100-07]==],category="bufffood",language="de",stock=false,channel="say",source="universal",migrationMatch=false,text=[==[Anständiges Essen vor einem schweren Weg ist selten eine schlechte Entscheidung.]==]}
A.DefaultEntries[#A.DefaultEntries+1]={id=[==[bufffood:de:regular:say:universal:native-0100-08]==],category="bufffood",language="de",stock=false,channel="say",source="universal",migrationMatch=false,text=[==[Wenn wir schon wagemutig werden, dann wenigstens nicht mit leerem Magen.]==]}
A.DefaultEntries[#A.DefaultEntries+1]={id=[==[bufffood:de:regular:say:universal:native-0100-09]==],category="bufffood",language="de",stock=false,channel="say",source="universal",migrationMatch=false,text=[==[Der Feind wird diese kleine Unterbrechung noch verkraften.]==]}
A.DefaultEntries[#A.DefaultEntries+1]={id=[==[bufffood:de:regular:say:universal:native-0100-10]==],category="bufffood",language="de",stock=false,channel="say",source="universal",migrationMatch=false,text=[==[Ein guter Koch erleichtert einer Reisegesellschaft mehr, als man ihm oft zugesteht.]==]}
