A.DefaultEntries[#A.DefaultEntries+1]={id=[==[bufffood:de:last:say:universal:native-0100-02]==],category="bufffood",language="de",stock=true,channel="say",source="universal",migrationMatch=false,text=[==[Von {item} habe ich nichts mehr. Wir sollten rechtzeitig einen Koch aufsuchen.]==]}
A.DefaultEntries[#A.DefaultEntries+1]={id=[==[bufffood:de:last:say:universal:native-0100-03]==],category="bufffood",language="de",stock=true,channel="say",source="universal",migrationMatch=false,text=[==[Die guten Vorräte sind bei mir aufgebraucht. Bitte berücksichtigt das beim nächsten Aufbruch.]==]}
A.DefaultEntries[#A.DefaultEntries+1]={id=[==[bufffood:de:last:say:universal:native-0100-04]==],category="bufffood",language="de",stock=true,channel="say",source="universal",migrationMatch=false,text=[==[Nur noch die leere Verpackung im Gepäck. Die zählt nicht als Vorbereitung.]==]}
A.DefaultEntries[#A.DefaultEntries+1]={id=[==[bufffood:de:last:say:universal:native-0100-05]==],category="bufffood",language="de",stock=true,channel="say",source="universal",migrationMatch=false,text=[==[Meine letzte Portion ist gegessen. Für einen weiteren Versuch brauche ich Nachschub.]==]}
A.DefaultEntries[#A.DefaultEntries+1]={id=[==[bufffood:de:last:say:universal:native-0100-06]==],category="bufffood",language="de",stock=true,channel="say",source="universal",migrationMatch=false,text=[==[Ich habe kein weiteres Reiseessen dabei. Das gehört auf unsere Liste.]==]}
