A.DefaultEntries[#A.DefaultEntries+1]={id=[==[bufffood:de:last:say:universal:native-0100-08]==],category="bufffood",language="de",stock=true,channel="say",source="universal",migrationMatch=false,text=[==[Das war mein letzter Vorrat dieser Sorte. Machen wir etwas Vernünftiges aus der Vorbereitung.]==]}
A.DefaultEntries[#A.DefaultEntries+1]={id=[==[elixir:de:regular:say:universal:native-0100-01]==],category="elixir",language="de",stock=false,channel="say",source="universal",migrationMatch=false,text=[==[Eine sorgfältig bemessene Dosis. Alchemie ist kein Wettrennen.]==]}
A.DefaultEntries[#A.DefaultEntries+1]={id=[==[elixir:de:regular:say:universal:native-0100-02]==],category="elixir",language="de",stock=false,channel="say",source="universal",migrationMatch=false,text=[==[Das Siegel sah ordentlich aus. Daran halte ich mich fürs Erste.]==]}
A.DefaultEntries[#A.DefaultEntries+1]={id=[==[elixir:de:regular:say:universal:native-0100-03]==],category="elixir",language="de",stock=false,channel="say",source="universal",migrationMatch=false,text=[==[Der Alchemist führt hoffentlich bessere Notizen, als seine Handschrift vermuten lässt.]==]}
A.DefaultEntries[#A.DefaultEntries+1]={id=[==[elixir:de:regular:say:universal:native-0100-04]==],category="elixir",language="de",stock=false,channel="say",source="universal",migrationMatch=false,text=[==[Ein wenig {item}, bevor wir der nächsten Schwierigkeit begegnen.]==]}
