A.DefaultEntries[#A.DefaultEntries+1]={id=[==[elixir:de:regular:say:universal:native-0100-06]==],category="elixir",language="de",stock=false,channel="say",source="universal",migrationMatch=false,text=[==[Über Geschmacksnoten sollten wir lieber erst reden, wenn alle fertig sind.]==]}
A.DefaultEntries[#A.DefaultEntries+1]={id=[==[elixir:de:regular:say:universal:native-0100-07]==],category="elixir",language="de",stock=false,channel="say",source="universal",migrationMatch=false,text=[==[Diese Flasche war für einen anspruchsvollen Tag gedacht. Das passt erschreckend gut.]==]}
A.DefaultEntries[#A.DefaultEntries+1]={id=[==[elixir:de:regular:say:universal:native-0100-08]==],category="elixir",language="de",stock=false,channel="say",source="universal",migrationMatch=false,text=[==[Lasst mich die Vorbereitung beenden, dann können wir weiter.]==]}
A.DefaultEntries[#A.DefaultEntries+1]={id=[==[elixir:de:regular:say:universal:native-0100-09]==],category="elixir",language="de",stock=false,channel="say",source="universal",migrationMatch=false,text=[==[Man kann ein Handwerk achten und seine Aromen trotzdem infrage stellen.]==]}
