A.DefaultEntries[#A.DefaultEntries+1]={id=[==[elixir:de:last:say:universal:native-0100-01]==],category="elixir",language="de",stock=true,channel="say",source="universal",migrationMatch=false,text=[==[Mein letzter Elixiervorrat ist verbraucht. Vor der nächsten Reise brauche ich einen Alchemisten.]==]}
A.DefaultEntries[#A.DefaultEntries+1]={id=[==[elixir:de:last:say:universal:native-0100-02]==],category="elixir",language="de",stock=true,channel="say",source="universal",migrationMatch=false,text=[==[Von {item} ist keine weitere Dosis da. Damit müssen wir jetzt planen.]==]}
A.DefaultEntries[#A.DefaultEntries+1]={id=[==[elixir:de:last:say:universal:native-0100-03]==],category="elixir",language="de",stock=true,channel="say",source="universal",migrationMatch=false,text=[==[Die letzte Flasche ist leer. Ich hätte noch eine mitnehmen sollen.]==]}
A.DefaultEntries[#A.DefaultEntries+1]={id=[==[elixir:de:last:say:universal:native-0100-04]==],category="elixir",language="de",stock=true,channel="say",source="universal",migrationMatch=false,text=[==[Mein Elixierbeutel ist inzwischen eher eine Glassammlung.]==]}
