A.DefaultEntries[#A.DefaultEntries+1]={id=[==[elixir:de:last:say:universal:native-0100-06]==],category="elixir",language="de",stock=true,channel="say",source="universal",migrationMatch=false,text=[==[Diese Vorbereitung ist aufgebraucht. Für die nächste Unternehmung muss ich sie erneuern.]==]}
