A.DefaultEntries[#A.DefaultEntries+1]={id=[==[elixir:de:last:say:universal:native-0100-08]==],category="elixir",language="de",stock=true,channel="say",source="universal",migrationMatch=false,text=[==[Das war mein letzter Vorrat. Ein Händlerbesuch wäre vor dem nächsten Aufbruch sinnvoll.]==]}
