A.DefaultEntries[#A.DefaultEntries+1]={id=[==[other:de:regular:say:universal:native-0100-01]==],category="other",language="de",stock=false,channel="say",source="universal",migrationMatch=false,text=[==[Jetzt darf {item} zeigen, weshalb ich dafür Platz im Gepäck freigehalten habe.]==]}
A.DefaultEntries[#A.DefaultEntries+1]={id=[==[other:de:regular:say:universal:native-0100-02]==],category="other",language="de",stock=false,channel="say",source="universal",migrationMatch=false,text=[==[Ich habe das für einen passenden Augenblick aufgehoben. Dieser dürfte genügen.]==]}
A.DefaultEntries[#A.DefaultEntries+1]={id=[==[other:de:regular:say:universal:native-0100-03]==],category="other",language="de",stock=false,channel="say",source="universal",migrationMatch=false,text=[==[Noch eine kleine Vorbereitung erledigt.]==]}
A.DefaultEntries[#A.DefaultEntries+1]={id=[==[other:de:regular:say:universal:native-0100-04]==],category="other",language="de",stock=false,channel="say",source="universal",migrationMatch=false,text=[==[Mitgebrachte Vorräte sollen uns helfen, nicht bloß wieder nach Hause getragen werden.]==]}
